    enunciado: "Durante la Semana Santa, en las casas de la Sierra se prepara la fanesca, una sopa espesa con doce granos y bacalao seco, acompa\u00f1ada de huevo duro, pl\u00e1tano frito, queso fresco y empanadas. La tradici\u00f3n dice que se comparte con familiares y vecinos. Do\u00f1a Carmen empieza desde el Mi\u00e9rcoles Santo porque los granos deben remojarse y pelarse, tarea que reparte entre sus hijas. El Jueves Santo recibe a sus comadres, que traen su propio plato de fanesca para intercambiar, y as\u00ed cada familia prueba la receta de las dem\u00e1s.\n\n\u00bfCu\u00e1l es la idea central del texto?",
