    nivel: "Avanzado",
    enunciado: "En el subcentro de salud de Portoviejo, la enfermera revis\u00f3 el carn\u00e9 de vacunaci\u00f3n de Camila, de un a\u00f1o. Explic\u00f3 a la mam\u00e1: \u201cTodo ni\u00f1o que recibi\u00f3 sus tres dosis a tiempo queda bien protegido. A Camila le falta la tercera dosis, as\u00ed que todav\u00eda no est\u00e1 del todo protegida\u201d. La mam\u00e1 pregunt\u00f3 si pod\u00eda vacunarla ese mismo d\u00eda y la enfermera respondi\u00f3 que s\u00ed, pero que deb\u00eda traer el carn\u00e9 en cada visita para llevar el control.\n\nCon la regla \u201csi recibi\u00f3 las tres dosis a tiempo, entonces est\u00e1 bien protegido\u201d y sabiendo que Camila NO est\u00e1 del todo protegida, \u00bfqu\u00e9 se concluye con certeza?",
