    enunciado: "Durante las fiestas de Quito, cada diciembre, las chivas rumberas recorren la ciudad con orquestas y bailarines. El grupo de oficina de Paola pag\u00f3 por adelantado quince d\u00f3lares por persona. El chofer avis\u00f3 que la chiva saldr\u00eda a las diez en punto y que no esperar\u00eda a nadie. Paola se hab\u00eda ido a comprar hielo y regres\u00f3 a las diez y cinco. La chiva ya se hab\u00eda ido y sus compa\u00f1eros no pudieron avisarle porque se qued\u00f3 sin bater\u00eda.\n\nSi el grupo ten\u00eda 8 personas, \u00bfcu\u00e1nto pagaron en total por adelantado?",
