    nivel: "Intermedio",
    enunciado: "El 2 de noviembre, en muchos barrios de Quito, las familias visitan los cementerios y llevan flores y comida para sus difuntos. En las calles aparecen puestos que venden colada morada y guaguas de pan. Don Wilson, panadero de Cotocollao, empieza a amasar desde las tres de la madrugada, porque sabe que la demanda aumenta a medida que avanza el d\u00eda y no quiere quedarse sin producto. Su hijo Joel, que estudia en Guayaquil, le cuenta por tel\u00e9fono que all\u00e1 la fecha tambi\u00e9n se recuerda con visitas al cementerio, pero con menos movimiento de colada y guaguas de pan.\n\n\u201cGuaguas de pan\u201d son:",
