    enunciado: "En la comunidad de Pilahu\u00edn, en Tungurahua, el camino hacia las parcelas se hab\u00eda da\u00f1ado con las lluvias. El presidente de la comunidad convoc\u00f3 a una minga: cada familia deb\u00eda enviar a un adulto con pala o pico el domingo a las seis de la ma\u00f1ana. Quienes no pod\u00edan asistir deb\u00edan pagar un reemplazo o aportar con materiales. Do\u00f1a Luc\u00eda no pudo ir porque cuidaba a su madre enferma, pero envi\u00f3 almuerzo para quince personas. Al final del d\u00eda el camino qued\u00f3 habilitado y la comunidad celebr\u00f3 con una pachamanca.\n\n\u201cMinga\u201d significa:",
