    enunciado: "A las cinco y media de la ma\u00f1ana, do\u00f1a Gladys instala su carrito en una esquina de Guayaquil. Vende bolones de verde con queso y caf\u00e9 pasado. Sus clientes principales son los obreros que entran a las seis y los estudiantes del colegio vecino que llegan a las siete. Si el d\u00eda amanece con lluvia, vende menos bolones porque la gente demora m\u00e1s en salir de casa, pero vende m\u00e1s caf\u00e9. Hoy llovi\u00f3 y, aunque vendi\u00f3 40 bolones menos de lo normal, tuvo que preparar dos termos de caf\u00e9 extra.\n\n\u00bfPor qu\u00e9 do\u00f1a Gladys vendi\u00f3 m\u00e1s caf\u00e9?",
