    nivel: "Intermedio",
    enunciado: "Cada a\u00f1o, en Latacunga, la fiesta de la Mama Negra re\u00fane a miles de personas en un desfile lleno de disfraces, m\u00fasica de bandas de pueblo y danzas. Los participantes representan personajes que mezclan tradiciones religiosas, ind\u00edgenas y mestizas. Muchos invitan comida y bebida a quienes los acompa\u00f1an en el recorrido, pues compartir es parte de la celebraci\u00f3n. Las familias preparan los trajes durante meses y quienes no desfilan arman puestos de comida a lo largo de las calles.\n\nEn el contexto, \u201cmestizas\u201d se refiere a tradiciones que:",
