    enunciado: "En junio, comunidades de Cotacachi celebran el Inti Raymi, una fiesta que agradece al sol y a la Pachamama por las cosechas. Hay bailes en c\u00edrculo con m\u00fasica de rondador y bombo, visitas de casa en casa y comidas compartidas. Para muchas familias, es un tiempo de reencuentro, pues los hijos que viven en otras ciudades regresan a la comunidad. Do\u00f1a Rosa dice: \u201cAqu\u00ed nadie se queda sin plato; el que llega a la casa, come\u201d.\n\n\u00bfQu\u00e9 se celebra en el Inti Raymi seg\u00fan el texto?",
