    enunciado: "\u2014\u00bfQu\u00e9 m\u00e1s, mi guagua? \u2014salud\u00f3 la t\u00eda Elena al ver a su sobrino. \u2014Aqu\u00ed nom\u00e1s, \u00f1a\u00f1a, sufriendo con el trabajo \u2014respondi\u00f3 \u00e9l\u2014. Ando chiro este mes. \u2014\u00a1No te hagas el chiro, que ayer te vi estrenando zapatos! \u2014Ya pues, t\u00eda, no sea cabeza dura. Eso fue en oferta. \u2014Bueno, mijo, entonces ahorra. Y cu\u00eddate del fr\u00edo, que hoy est\u00e1 achachay.\n\n\u00bfCu\u00e1l afirmaci\u00f3n es FALSA?",
    opciones: ["La t\u00eda le recomienda ahorrar", "El sobrino dijo andar chiro", "El sobrino explic\u00f3 que los zapatos eran un regalo", "Los zapatos fueron en oferta"],
