    enunciado: "La escala de pH mide qu\u00e9 tan \u00e1cida o b\u00e1sica es una sustancia y va, habitualmente, de 0 a 14. Un valor de 7 corresponde a una sustancia neutra, como el agua pura a 25 \u00b0C; los valores menores a 7 indican acidez y los mayores a 7, basicidad. La escala es logar\u00edtmica: cada unidad de diferencia equivale a un cambio de diez veces en la concentraci\u00f3n de iones hidr\u00f3geno. As\u00ed, una sustancia con pH 3 es diez veces m\u00e1s \u00e1cida que una con pH 4 y cien veces m\u00e1s \u00e1cida que una con pH 5. El jugo de lim\u00f3n tiene un pH cercano a 2, el caf\u00e9 alrededor de 5, la sangre cerca de 7,4 y el bicarbonato de sodio disuelto, cerca de 8,3. Por eso no es correcto pensar que pasar de pH 2 a pH 4 es un cambio peque\u00f1o: en realidad implica cien veces menos acidez.\n\n\u00bfCu\u00e1ntas veces es m\u00e1s \u00e1cido el jugo de lim\u00f3n (pH 2) que el caf\u00e9 (pH 5)?",
