    enunciado: "En gen\u00e9tica mendeliana, un car\u00e1cter puede estar determinado por dos alelos, uno heredado de cada progenitor. Si el alelo dominante (A) est\u00e1 presente, el rasgo dominante se manifiesta; el rasgo recesivo solo aparece cuando el individuo tiene dos alelos recesivos (aa). Cuando se cruzan dos individuos heterocigotos (Aa \u00d7 Aa), el cuadro de Punnett muestra cuatro combinaciones posibles: AA, Aa, Aa y aa. Esto significa que la probabilidad de obtener un descendiente con el rasgo recesivo es de una entre cuatro, es decir, 25 %, mientras que la probabilidad de que muestre el rasgo dominante es de 75 %. En cambio, si se cruza un individuo homocigoto dominante (AA) con uno homocigoto recesivo (aa), todos los descendientes ser\u00e1n Aa y mostrar\u00e1n el rasgo dominante, aunque llevar\u00e1n el alelo recesivo.\n\nEn el cruce Aa \u00d7 Aa, \u00bfqu\u00e9 probabilidad hay de obtener un descendiente aa?",
