    subtema: "Anatom\u00eda \u00b7 Respiraci\u00f3n \u00b7 Causa-consecuencia",
    nivel: "Intermedio",
    enunciado: "La respiraci\u00f3n depende de la acci\u00f3n coordinada del diafragma, un m\u00fasculo con forma de c\u00fapula ubicado bajo los pulmones, y de los m\u00fasculos intercostales. Durante la inspiraci\u00f3n, el diafragma se contrae y desciende, mientras que las costillas se elevan; esto aumenta el volumen de la caja tor\u00e1cica y disminuye la presi\u00f3n en el interior de los pulmones, por lo que el aire entra desde el exterior, donde la presi\u00f3n es mayor. En la espiraci\u00f3n, el diafragma se relaja y vuelve a su posici\u00f3n, el volumen disminuye, la presi\u00f3n aumenta y el aire sale. En los alv\u00e9olos pulmonares, el ox\u00edgeno pasa a la sangre y el di\u00f3xido de carbono pasa al aire que ser\u00e1 expulsado. Este intercambio de gases se produce por difusi\u00f3n, es decir, desde donde hay mayor concentraci\u00f3n hacia donde hay menor.\n\n\u00bfPor qu\u00e9 entra aire a los pulmones durante la inspiraci\u00f3n?",
