    nivel: "Avanzado",
    enunciado: "La bater\u00eda de un autom\u00f3vil almacena la energ\u00eda necesaria para arrancar el motor, mientras que el alternador la recarga y alimenta los sistemas el\u00e9ctricos cuando el motor est\u00e1 en marcha. Una bater\u00eda de 12 voltios en buen estado marca alrededor de 12,6 voltios con el motor apagado. Con el motor encendido, el alternador deber\u00eda elevar la tensi\u00f3n a un valor de entre 13,8 y 14,4 voltios. Si el volt\u00edmetro marca 12,2 voltios con el motor funcionando, significa que el alternador no est\u00e1 cargando correctamente y la bater\u00eda se ir\u00e1 descargando hasta que el veh\u00edculo no arranque. Una banda floja o desgastada, o un regulador defectuoso, pueden ser causas de esa falla. Por eso, ante luces tenues y arranque d\u00e9bil, conviene medir tanto la bater\u00eda como el alternador antes de reemplazar piezas.\n\nSi con el motor encendido el volt\u00edmetro marca 12,2 V, \u00bfqu\u00e9 se puede concluir?",
