    enunciado: "Dos magnitudes son directamente proporcionales cuando, al aumentar una, la otra aumenta en la misma raz\u00f3n. La regla de tres directa permite resolver problemas con esta relaci\u00f3n. Por ejemplo, una camioneta consume 15 galones de combustible al recorrer 300 kil\u00f3metros. Si se mantiene el mismo tipo de carretera y manejo, para recorrer 450 kil\u00f3metros consumir\u00e1 22,5 galones. Esto equivale a un rendimiento de 20 kil\u00f3metros por gal\u00f3n. Sin embargo, la proporcionalidad es solo una aproximaci\u00f3n: la velocidad, la carga y el estado de la v\u00eda pueden modificar el consumo real. Por eso, en la pr\u00e1ctica, los transportistas a\u00f1aden un margen de seguridad al calcular el combustible que necesitar\u00e1n.\n\n\u00bfCu\u00e1ntos galones consumir\u00e1 la camioneta en 450 km?",
