    enunciado: "Un problema con dos inc\u00f3gnitas puede resolverse planteando un sistema de ecuaciones. En un evento ben\u00e9fico se vendieron 100 entradas entre adultos y ni\u00f1os. Cada entrada de adulto cost\u00f3 5 d\u00f3lares y cada entrada de ni\u00f1o, 3 d\u00f3lares, y se recaudaron 380 d\u00f3lares en total. Si x es el n\u00famero de adultos y y el de ni\u00f1os, las ecuaciones son x + y = 100 y 5x + 3y = 380. Al sustituir y = 100 \u2212 x en la segunda ecuaci\u00f3n, resulta 5x + 300 \u2212 3x = 380, de donde 2x = 80 y x = 40. Por tanto, asistieron 40 adultos y 60 ni\u00f1os. Para verificar, se comprueba que 40 \u00d7 5 + 60 \u00d7 3 da 380, lo que confirma la soluci\u00f3n.\n\n\u00bfCu\u00e1ntos ni\u00f1os compraron entrada?",
