    enunciado: "En ausencia de resistencia del aire, todos los objetos que caen cerca de la superficie terrestre aceleran de la misma manera, con una aceleraci\u00f3n aproximada de 9,8 metros por segundo cada segundo. Esto significa que, partiendo del reposo, la velocidad de un cuerpo aumenta unos 9,8 metros por segundo en cada segundo. Despu\u00e9s de 2 segundos, la velocidad es de 19,6 metros por segundo, y la distancia recorrida es de unos 19,6 metros. Despu\u00e9s de 3 segundos, la velocidad llega a 29,4 metros por segundo y la distancia a 44,1 metros. Aunque la experiencia diaria sugiere que los objetos pesados caen m\u00e1s r\u00e1pido, esa diferencia se debe a que el aire frena m\u00e1s a los cuerpos ligeros y de gran superficie, como una hoja, y no a que la gravedad los atraiga de distinta forma.\n\n\u00bfPor qu\u00e9 una hoja cae m\u00e1s lento que una piedra en el aire?",
