    enunciado: "El sistema inmunitario defiende al cuerpo frente a microorganismos como virus y bacterias. Cuando un agente extra\u00f1o ingresa por primera vez, ciertas c\u00e9lulas lo reconocen y producen anticuerpos, prote\u00ednas que se unen a \u00e9l y facilitan su eliminaci\u00f3n. Este proceso tarda varios d\u00edas, por lo que durante ese tiempo la persona puede enfermar. Parte de las c\u00e9lulas involucradas se convierten en c\u00e9lulas de memoria, que permanecen durante a\u00f1os y reaccionan m\u00e1s r\u00e1pido y con m\u00e1s fuerza si el mismo agente vuelve a aparecer. Las vacunas aprovechan este mecanismo: presentan al organismo una forma inactiva, debilitada o un fragmento del agente, sin causar la enfermedad grave, para que genere memoria inmunitaria. Por eso, una persona vacunada que se expone al microorganismo suele enfermar menos o no enfermar.\n\n\u00bfQu\u00e9 hacen los anticuerpos?",
    opciones: ["Producen virus", "Transportan ox\u00edgeno", "Destruyen los \u00f3rganos", "Se unen al agente extra\u00f1o y facilitan su eliminaci\u00f3n"],
    respuestaCorrecta: 3,
