    enunciado: "Ecuador genera la mayor parte de su electricidad en centrales hidroel\u00e9ctricas, que aprovechan la fuerza del agua de los r\u00edos. Esta fuente es limpia y de bajo costo operativo, pero depende de las lluvias: cuando hay sequ\u00edas prolongadas, los embalses y caudales bajan y la producci\u00f3n disminuye, como ocurri\u00f3 en per\u00edodos de estiaje que obligaron a racionar la energ\u00eda. Frente a este riesgo, los especialistas proponen diversificar la matriz energ\u00e9tica con energ\u00eda solar, e\u00f3lica y otras fuentes, adem\u00e1s de mejorar el mantenimiento y reducir las p\u00e9rdidas en la red. Tambi\u00e9n se recomienda promover el ahorro, por ejemplo, cambiando focos incandescentes por LED y usando electrodom\u00e9sticos eficientes. De este modo, la seguridad energ\u00e9tica no depender\u00eda de una sola fuente ni de la variabilidad del clima.\n\n\u00bfQu\u00e9 propone el texto?",
