    opciones: ["Una intoxicaci\u00f3n por comida coste\u00f1a.", "La adaptaci\u00f3n del cuerpo a la altura.", "Una infecci\u00f3n grave que requiere cirug\u00eda.", "El estr\u00e9s del seminario \u00fanicamente."],
    respuestaCorrecta: 1,
