    enunciado: "\u2014\u00bfVamos al cine esta noche? \u2014\u00a1De una!\n\n\u00bfQu\u00e9 expresa \u00ab\u00a1De una!\u00bb en este di\u00e1logo?",
    opciones: ["Aceptaci\u00f3n inmediata.", "Rechazo cort\u00e9s.", "Duda.", "Sorpresa desagradable."],
