    subtema: "Modismos ecuatorianos \u00b7 Modismos",
    nivel: "B\u00e1sico",
    enunciado: "\u2014Qu\u00e9 bac\u00e1n tu moto nueva, \u00bfcu\u00e1nto te cost\u00f3? \u2014pregunt\u00f3 Jefferson.\n\n\u00bfQu\u00e9 quiere decir \u00abbac\u00e1n\u00bb?",
