    tema: "Lectura comprensiva",
    subtema: "Modismos ecuatorianos \u00b7 Modismos",
    nivel: "Intermedio",
    enunciado: "\u2014Tu primo estaba jincho en la boda y se puso a bailar sobre la mesa \u2014cont\u00f3 Lorena entre risas.\n\n\u00bfQu\u00e9 significa \u00abjincho\u00bb?",
    opciones: ["Dormido.", "Cansado.", "Ebrio.", "Enamorado."],
    respuestaCorrecta: 2,
    explicacion: "\u00abJincho\u00bb se usa para referirse a alguien que ha bebido en exceso. La conducta descrita lo confirma.",
