    tema: "Lectura comprensiva",
    subtema: "Modismos ecuatorianos \u00b7 Modismos",
    nivel: "B\u00e1sico",
    enunciado: "\u2014No me friegues, que estoy estudiando \u2014le dijo Daniela a su hermano, que le hac\u00eda cosquillas.\n\n\u00bfQu\u00e9 le pide Daniela con \u00abno me friegues\u00bb?",
    opciones: ["Que deje de molestarla.", "Que le ayude a estudiar.", "Que le traiga comida.", "Que salga de la casa."],
    respuestaCorrecta: 0,
    explicacion: "\u00abFregar\u00bb es molestar o fastidiar. \u00abNo me friegues\u00bb es pedir que no la moleste.",
