    tema: "Lectura comprensiva",
    subtema: "Modismos ecuatorianos \u00b7 Modismos",
    nivel: "Intermedio",
    enunciado: "\u2014Los fines de semana hago un cachuelo en una pizzer\u00eda para ayudarme con la pensi\u00f3n \u2014coment\u00f3 Bryan.\n\n\u00bfQu\u00e9 es un \u00abcachuelo\u00bb?",
    opciones: ["Un pr\u00e9stamo bancario.", "Un trabajo ocasional.", "Una beca.", "Un castigo escolar."],
    respuestaCorrecta: 1,
    explicacion: "\u00abCachuelo\u00bb designa un trabajo temporal u ocasional que se hace para ganar un dinero extra.",
