    subtema: "Modismos ecuatorianos \u00b7 Modismos",
    nivel: "B\u00e1sico",
    enunciado: "\u2014\u00bfQuieres sopa? \u2014\u00bfMande? \u2014Que si quieres sopa.\n\n\u00bfQu\u00e9 indica el \u00ab\u00bfmande?\u00bb del segundo hablante?",
    opciones: ["Que quiere ordenar algo.", "Que est\u00e1 enojado.", "Que no escuch\u00f3 bien y pide que repitan.", "Que rechaza la sopa."],
