    nivel: "B\u00e1sico",
    enunciado: "\u2014Esa guambra del barrio canta hermoso, deber\u00edamos invitarla a la fiesta \u2014sugiri\u00f3 Marco.\n\n\u00bfA qui\u00e9n se refiere \u00abguambra\u00bb?",
    opciones: ["A una se\u00f1ora mayor.", "A una cantante famosa.", "A una profesora.", "A una chica joven."],
