    tema: "Lectura comprensiva",
    subtema: "Modismos ecuatorianos \u00b7 Modismos",
    nivel: "Intermedio",
    enunciado: "\u2014Ese jugador tiene mucho \u00f1eque: aunque iba perdiendo, nunca se rindi\u00f3 y empat\u00f3 al final \u2014dijo el comentarista.\n\n\u00bfQu\u00e9 significa \u00abtener \u00f1eque\u00bb?",
    opciones: ["Tener fuerza y empe\u00f1o.", "Tener mala suerte.", "Tener mucho dinero.", "Tener gran estatura."],
