    area: "Conocimiento",
    tema: "Lectura comprensiva",
    subtema: "Modismos ecuatorianos \u00b7 Modismos",
    nivel: "Intermedio",
    enunciado: "\u2014De pana te digo que yo no fui, Carlos \u2014insisti\u00f3 Paola.\n\n\u00bfQu\u00e9 expresa \u00abde pana\u00bb en este contexto?",
    opciones: ["Con enojo.", "Con apuro.", "Con sinceridad.", "Con burla."],
    respuestaCorrecta: 2,
    explicacion: "\u00abDe pana\u00bb equivale a \u00abde verdad\u00bb o \u00aben serio\u00bb. Paola afirma con sinceridad que no fue ella.",
