    subtema: "Idiosincrasia Costa \u00b7 Inferencia",
    nivel: "Intermedio",
    enunciado: "En la tienda de su barrio, Do\u00f1a Mary anota en un cuaderno lo que los vecinos \u00abf\u00edan\u00bb y se lo cobra a fin de mes. Nunca pide documentos ni garant\u00edas, porque conoce a cada familia.\n\n\u00bfQu\u00e9 se infiere de esta pr\u00e1ctica?",
    opciones: ["Que la tienda est\u00e1 a punto de quebrar.", "Que existe una relaci\u00f3n de confianza entre vecinos.", "Que los clientes nunca pagan.", "Que est\u00e1 prohibido vender a cr\u00e9dito."],
