    enunciado: "Un alba\u00f1il de Machala trabajaba al mediod\u00eda sin tomar agua y se desmay\u00f3. Sus compa\u00f1eros lo llevaron a la sombra y le mojaron la cabeza. El supervisor decidi\u00f3 que desde entonces habr\u00eda pausas con agua en las horas de m\u00e1s calor.\n\n\u00bfQu\u00e9 medida preventiva es la m\u00e1s adecuada seg\u00fan el texto?",
