    enunciado: "En las islas Gal\u00e1pagos, los visitantes deben ir acompa\u00f1ados de un gu\u00eda naturalista autorizado, mantener distancia de los animales y no sacar rocas ni plantas. Quienes incumplen reciben multas.\n\n\u00bfQu\u00e9 se infiere de estas normas?",
