    enunciado: "Hoy es com\u00fan encontrar fanesca en restaurantes de Guayaquil y encebollado en Quito. Las familias que migraron entre regiones llevaron sus recetas y costumbres a sus nuevas ciudades.\n\n\u00bfQu\u00e9 se infiere del texto?",
