    enunciado: "Cada ma\u00f1ana, Josu\u00e9 y su hermana caminan una hora entre cerros para llegar a la escuela. Cuando llueve, el camino se enloda y a veces no pueden asistir.\n\n\u00bfQu\u00e9 se infiere del caso?",
    opciones: ["Que a los ni\u00f1os no les gusta estudiar.", "Que la escuela est\u00e1 al lado de su casa.", "Que la lluvia mejora los caminos.", "Que el acceso a la educaci\u00f3n rural puede verse limitado por la distancia y el clima."],
