    opciones: ["Que es una obligaci\u00f3n escolar.", "Que la reuni\u00f3n semanal fortalece los lazos familiares.", "Que los abuelos viven solos y no quieren visitas.", "Que los ni\u00f1os no disfrutan la reuni\u00f3n."],
    respuestaCorrecta: 1,
    explicacion: "Cocinar juntos, conversar y llegar temprano desde lejos muestran el valor que la familia da a esos encuentros.",
