    enunciado: "Muchas palabras del espa\u00f1ol ecuatoriano vienen del kichwa: \u00abguagua\u00bb (ni\u00f1o), \u00abyapa\u00bb (extra), \u00abchuchaqui\u00bb (resaca) y \u00ab\u00f1a\u00f1o\u00bb (hermano).\n\n\u00bfQu\u00e9 refleja este fen\u00f3meno?",
    opciones: ["El contacto hist\u00f3rico y la influencia del kichwa en el espa\u00f1ol del pa\u00eds.", "Que el espa\u00f1ol ecuatoriano no tiene palabras propias.", "Que el kichwa dej\u00f3 de hablarse hace siglos.", "Que el idioma oficial es el kichwa."],
