    enunciado: "Entre junio y septiembre llegan ballenas jorobadas a las costas de Puerto L\u00f3pez. En esos meses, muchos pescadores gu\u00edan excursiones tur\u00edsticas para observarlas y los hoteles se llenan.\n\n\u00bfQu\u00e9 se infiere de la econom\u00eda local?",
