    enunciado: "En los mercados, las vendedoras suelen llamar a los clientes \u00abmi reina\u00bb, \u00abmi rey\u00bb o \u00abvecina\u00bb, y suelen regalarles una yapa. Muchos compradores regresan siempre al mismo puesto.\n\n\u00bfQu\u00e9 se infiere de ese trato?",
